<template>
  <el-drawer :model-value="modelValue" :title="`${categoryLabel} · 月份对账`" size="min(920px, 96vw)" @close="close">
    <div class="monthly-toolbar"><el-date-picker v-model="month" type="month" value-format="YYYY-MM" format="YYYY年MM月" placeholder="选择月份"/><el-select v-if="available.length" :model-value="month" aria-label="已有月份" @change="month=$event"><el-option v-for="item in available" :key="item" :label="item" :value="item"/></el-select><el-button v-if="detailMode && !props.partyId" @click="backToParties">返回全部往来单位</el-button><el-select v-if="detailMode" v-model="tab" aria-label="对账内容"><el-option label="单据" value="documents"/><el-option label="付款" value="payments"/></el-select><span>{{selectedParty?.party_name||partyName||'全部往来单位'}}</span><el-button :loading="exporting" @click="exportReport">导出月度对账</el-button></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false"/>
    <div v-if="summary" class="monthly-metrics"><div><small>月期初应付额</small><strong>{{money(summary.opening_payable)}}</strong></div><button class="metric-button" @click="selectPayments"><small>本月付款额 · 查看付款</small><strong>{{money(summary.paid_amount)}}</strong></button><div><small>剩余应付</small><strong>{{money(summary.remaining_amount)}}</strong></div><div><small>本月新增应付</small><strong>{{money(summary.new_payable)}}</strong></div><div><small>定金抵扣</small><strong>{{money(summary.applied_amount)}}</strong></div><div><small>历史已付</small><strong>{{money(summary.historical_paid_amount)}}</strong></div><div><small>期初预付 / 超付</small><strong>{{money(summary.opening_credit)}}</strong></div><div><small>期末预付 / 超付</small><strong>{{money(summary.credit_balance)}}</strong></div><div><small>待核对应付的本月付款</small><strong>{{money(summary.unknown_payment_amount)}}</strong></div></div>
    <template v-if="summary"><h4>本月实际付款性质（按币种分行）</h4><el-table :data="summary.paid_nature_by_currency||[]" border size="small"><el-table-column prop="currency" label="币种"/><el-table-column prop="corporate" label="对公 / 正报"/><el-table-column prop="personal" label="对私"/><el-table-column prop="unknown" label="性质待确认"/></el-table><h4>分类应付余额（按往来单位、币种和性质；按当前来源重建，不是历史冻结值）</h4><el-table :data="summary.nature_balances||[]" border size="small" empty-text="暂无可分类余额"><el-table-column prop="party_name" label="往来单位" min-width="180"/><el-table-column prop="currency" label="币种" min-width="110"/><el-table-column label="性质" min-width="100"><template #default="{row}">{{natureLabel(row.nature)}}</template></el-table-column><el-table-column min-width="125" label="期初应付"><template #default="{row}">{{row.opening_payable==null?'待核对':row.opening_payable}}</template></el-table-column><el-table-column min-width="125" label="期初预付 / 超付"><template #default="{row}">{{row.opening_credit==null?'待核对':row.opening_credit}}</template></el-table-column><el-table-column min-width="125" prop="new_payable" label="本月新增应付"/><el-table-column min-width="125" prop="paid_amount" label="本月付款"/><el-table-column min-width="125" prop="historical_paid_amount" label="历史已付"/><el-table-column min-width="125" label="剩余应付"><template #default="{row}">{{row.remaining_amount==null?'待核对':row.remaining_amount}}</template></el-table-column><el-table-column min-width="145" prop="reference_remaining_amount" label="参考应付（待核实时仅供参考）"/><el-table-column min-width="160" label="分类付款超出应付"><template #default="{row}">{{row.credit_balance==null?'待核对':row.credit_balance}}</template></el-table-column><el-table-column min-width="160" prop="reference_credit_balance" label="参考分类付款超额（未核实）"/><el-table-column min-width="125" prop="current_plan_amount" label="剩余计划金额"/><el-table-column prop="source_number" label="待核对来源" min-width="200"/><el-table-column label="核对状态" min-width="100"><template #default="{row}">{{row.nature==='unknown'||row.needs_review?'待核对':'—'}}</template></el-table-column></el-table><p class="hint">分类余额按当前可识别来源重建，并非历史冻结结果；不同币种不做换算，待核对分类之间不合并抵销。</p><h4>本月当前付款计划（扣除已核销，非历史冻结值）</h4><el-table :data="planRows" border size="small" empty-text="本月没有当前计划"><el-table-column prop="due_date" label="计划到期日"/><el-table-column prop="party_name" label="往来单位"/><el-table-column prop="currency" label="币种"/><el-table-column label="性质"><template #default="{row}">{{natureLabel(row.nature)}}</template></el-table-column><el-table-column prop="original_amount" label="原计划金额"/><el-table-column prop="paid_amount" label="已核销金额"/><el-table-column prop="amount" label="剩余计划金额"/><el-table-column prop="reserved_amount" label="审批占用金额"/><el-table-column prop="available_amount" label="可申请金额"/><el-table-column prop="label" label="款项名称"/></el-table></template>
    <p v-if="summary" class="hint">待核对 {{summary.unknown_documents||0}} 张 · 缺少日期 {{summary.undated_documents||0}} 张。该汇总基于当前可识别单据；缺少日期或待核对项目可能影响月份归属。</p><p v-for="notice in notices" :key="notice" class="hint">{{notice}}</p><el-alert v-if="downloadError" :title="downloadError" type="error" :closable="false"/>
    <template v-if="detailMode && tab==='documents'">
      <div class="payment-status-filter" role="group" aria-label="单据付款状态">
        <button v-for="option in paymentStatusOptions" :key="option.value" type="button" :aria-pressed="paymentStatus===option.value" @click="selectPaymentStatus(option.value)">{{option.label}} <span>{{documentStatusCounts?.[option.value] ?? '—'}}</span></button>
      </div>
      <p class="hint">按所选月份期末余额区分，未付款包含部分付款；定金抵扣计入结清判断。上方汇总显示该范围全部单据，不随付款状态筛选变化。</p>
    </template>
    <el-table v-if="partiesMode" :data="rows" v-loading="loading" border empty-text="当前范围没有记录">
      <el-table-column label="往来单位" min-width="220"><template #default="{row}"><el-button link type="primary" @click="selectParty(row)">{{row.party_name||'未分配往来单位'}}</el-button><small v-if="row.unknown_documents||row.undated_documents" class="party">待核对 {{row.unknown_documents||0}} 张 · 缺少日期 {{row.undated_documents||0}} 张</small></template></el-table-column>
      <el-table-column prop="opening_payable" label="期初应付"><template #default="{row}">{{money(row.opening_payable)}}</template></el-table-column><el-table-column prop="paid_amount" label="本月付款"><template #default="{row}">{{money(row.paid_amount)}}</template></el-table-column><el-table-column prop="remaining_amount" label="剩余应付"><template #default="{row}">{{money(row.remaining_amount)}}</template></el-table-column>
    </el-table>
    <el-table v-else :data="rows" v-loading="loading" border empty-text="当前范围没有记录">
      <template v-if="tab==='documents'"><el-table-column label="付款状态" width="110"><template #default="{row}"><el-tag :type="paymentStatusType(row.payment_status)" size="small">{{paymentStatusLabel(row.payment_status)}}</el-tag></template></el-table-column><el-table-column label="单号" min-width="230"><template #default="{row}"><el-button link type="primary" @click="openDocument(row)">{{row.number}}</el-button><el-button v-if="props.queue==='supplier' && row.kind==='shipment' && Number.isSafeInteger(Number(row.id)) && Number(row.id)>0" link @click="openShipment(row)">发货明细</el-button><small class="party">{{row.party_name}}</small></template></el-table-column><el-table-column label="单据时间" min-width="155"><template #default="{row}">{{formatDocumentTime(row.document_time)||'未记录'}}</template></el-table-column><el-table-column v-for="f in documentMoneyFields" :key="f" :prop="f" :label="balanceLabel(f)" min-width="115"><template #default="{row}">{{money(row[f])}}</template></el-table-column><el-table-column prop="unknown_reason" label="待核对原因" min-width="160"/></template>
      <template v-else><el-table-column label="付款日期" width="120"><template #default="{row}">{{formatDocumentTime(row.date)||'未记录'}}<el-tag v-if="row.date_inferred" type="warning" size="small">账期月末推定</el-tag></template></el-table-column><el-table-column label="单位 / 付款单号" min-width="190"><template #default="{row}">{{row.party_name}} · {{row.number}}<el-tag v-if="row.is_reversal" size="small" type="warning">冲销</el-tag></template></el-table-column><el-table-column label="金额" width="130"><template #default="{row}">{{money(row.amount)}}</template></el-table-column><el-table-column label="参考号 / 备注" min-width="170"><template #default="{row}">{{row.reference_number||'—'}}<p class="hint">{{row.notes?.split('\n')[0]||''}}</p></template></el-table-column><el-table-column label="原始转账凭据" min-width="220"><template #default="{row}"><template v-if="row.vouchers?.length"><span v-for="file in row.vouchers" :key="file.id" class="voucher"><el-button link type="primary" @click="preview(row,file)">{{file.file_name}}</el-button><el-button link @click="download(row,file)">下载</el-button></span></template><span v-else class="muted">待补转账凭据</span></template></el-table-column></template>
    </el-table><el-pagination :current-page="page" :total="count" :page-size="20" layout="total,prev,pager,next" @current-change="changePage"/>
    <el-dialog v-model="previewOpen" title="原始转账凭据" width="min(900px, 94vw)" @closed="releasePreview"><img v-if="previewType.startsWith('image/')" :src="previewUrl" class="preview-image"/><iframe v-else-if="previewType==='application/pdf'" :src="previewUrl" class="preview-pdf" title="转账凭据 PDF"/><p v-else>该文件格式不支持在线预览，请下载查看。</p></el-dialog>
  </el-drawer>
</template>
<script setup>
import {computed, onUnmounted, ref, watch} from 'vue';
import {fetchMonthlyPayables,downloadMonthlyPayables} from '../../api/supplyDashboardV2';
import {openMonthlyShipment} from '../../utils/monthlyShipmentDrilldown';
import {fetchApiFile, downloadApiFile} from '../../api/request';
import {paymentVoucherUrl} from '../../api/supplyCostsV2';
import {useAuthStore} from '../../stores/auth';
import {cockpitActorKey} from '../../utils/cockpitDraft';
import {formatDocumentTime} from '../../utils/supplyDocumentTime';
const props=defineProps({modelValue:Boolean,queue:{type:String,default:'supplier'},countryId:[String,Number],partyId:[String,Number],partyName:String,partyType:String});
const categoryLabel=computed(()=>({supplier:'供应商货款',domestic:'国内运费',carrier:'批次货运费',clearance:'入库清关费用',deposit:'采购定金'})[props.queue]);
const emit=defineEmits(['update:modelValue','open']);
const auth=useAuthStore(), month=ref(shanghaiMonth()),tab=ref('documents'),selectedParty=ref(null),globalPayments=ref(false),rows=ref([]),summary=ref(null),planRows=ref([]),count=ref(0),available=ref([]),notices=ref([]),loading=ref(false),exporting=ref(false),error=ref(''),downloadError=ref(''),page=ref(1);
const partiesMode=computed(()=>!props.partyId&&!selectedParty.value&&!globalPayments.value),detailMode=computed(()=>!partiesMode.value);
const paymentStatus=ref('unpaid'),documentStatusCounts=ref(null);
const paymentStatusOptions=[{value:'unpaid',label:'未付款'},{value:'paid',label:'已付款'},{value:'unknown',label:'待核对'},{value:'all',label:'全部'}];
const paymentStatusLabel=value=>({unpaid:'未付款',partial:'部分付款',paid:'已付款',unknown:'待核对'})[value]||'待核对';
const paymentStatusType=value=>({unpaid:'danger',partial:'warning',paid:'success',unknown:'info'})[value]||'info';
const natureLabel=value=>({corporate:'对公 / 正报',personal:'对私',unknown:'性质待确认'})[value]||'性质待确认';
function selectPaymentStatus(value){paymentStatus.value=value;}
let generation=0,previewGeneration=0;const previewUrl=ref(''),previewType=ref(''),previewOpen=ref(false);
function shanghaiMonth(){const parts=new Intl.DateTimeFormat('en',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).formatToParts(new Date());return `${parts.find(p=>p.type==='year').value}-${parts.find(p=>p.type==='month').value}`;}
const money=v=>v==null?'待核对':Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:4});
const documentMoneyFields=['opening_payable','new_payable','paid_amount','applied_amount','historical_paid_amount','remaining_amount','credit_balance'];
function balanceLabel(k){return ({opening_payable:'期初应付',new_payable:'新增应付',paid_amount:'已付',applied_amount:'抵扣',historical_paid_amount:'历史已付',remaining_amount:'剩余应付',credit_balance:'期末预付 / 超付'})[k]||k;}
function openDocument(row){emit('open',{kind:row.kind,id:row.id,number:row.number,href:`/supply-chain/costs?${new URLSearchParams({kind:row.kind,id:row.id})}`});}
function invalidateDetailResources(){downloadError.value='';previewOpen.value=false;releasePreview();}
function selectPayments(){if(!props.partyId&&!selectedParty.value)globalPayments.value=true;if(tab.value!=='payments'){tab.value='payments';page.value=1;}}
function selectParty(row){invalidateDetailResources();paymentStatus.value='unpaid';selectedParty.value={...row};globalPayments.value=false;tab.value='documents';page.value=1;}
function backToParties(){invalidateDetailResources();paymentStatus.value='unpaid';selectedParty.value=null;globalPayments.value=false;tab.value='documents';page.value=1;}
function close(){emit('update:modelValue',false);}
function scopeParams(){const selected=selectedParty.value;return {queue:props.queue,month:month.value,...(props.partyType?{party_type:props.partyType}:{}),...(props.countryId?{country_id:props.countryId}:{}),...(props.partyId?{party_id:props.partyId}:selected?(selected.party_id?{party_id:selected.party_id}:{unassigned_party:true}):{})};}
async function exportReport(){exporting.value=true;downloadError.value='';try{const result=await downloadMonthlyPayables(scopeParams());if(result?.success===false)throw new Error(result.message||"月度对账导出失败");}catch(e){downloadError.value=e.message||'月度对账导出失败';}finally{exporting.value=false;}}
async function load(){const token=++generation;rows.value=[];summary.value=null;planRows.value=[];documentStatusCounts.value=null;available.value=[];notices.value=[];error.value='';if(!props.modelValue||auth.authorizationStale||!month.value){count.value=0;loading.value=false;return;}loading.value=true;const params={...scopeParams(),view:partiesMode.value?'parties':tab.value,...(!partiesMode.value&&tab.value==='documents'?{payment_status:paymentStatus.value}:{}),limit:20,offset:(page.value-1)*20};try{const r=await fetchMonthlyPayables(params);if(token!==generation)return;if(!r?.success)throw new Error(r?.message||'月份对账读取失败');const d=r.data||{};rows.value=d.rows||[];summary.value=d.summary||null;planRows.value=d.current_plan_rows||[];documentStatusCounts.value=d.document_status_counts||null;count.value=Number(d.count||0);available.value=d.available_months||[];notices.value=d.notices||[];}catch(e){if(token===generation)error.value=e.message||'月份对账读取失败';}finally{if(token===generation)loading.value=false;}}
function changePage(v){if(v===page.value)return;page.value=v;load();}
function openShipment(row){if(props.queue!=='supplier'||row?.kind!=='shipment'||!Number.isSafeInteger(Number(row.id))||Number(row.id)<1||!/^\d{4}-(0[1-9]|1[0-2])$/.test(month.value||''))return;openMonthlyShipment(Number(row.id),month.value);}
function fileUrl(row,file){return paymentVoucherUrl(row.kind,row.source_id,row.voucher_payment_id||row.id,file.id);}
async function preview(row,file){const token=++previewGeneration;try{const result=await fetchApiFile(fileUrl(row,file));if(token!==previewGeneration)return;if(!result?.success||!result.blob)throw new Error(result?.message||'凭据读取失败');releasePreview();previewType.value=file.content_type||result.blob.type||'';previewUrl.value=URL.createObjectURL(new Blob([result.blob],{type:previewType.value}));previewOpen.value=true;}catch(e){if(token===previewGeneration)error.value=e.message||'凭据读取失败';}}
async function download(row,file){downloadError.value='';try{const result=await downloadApiFile(fileUrl(row,file),file.file_name);if(result?.success===false)throw new Error(result.message||'凭据下载失败');}catch(e){downloadError.value=e.message||'凭据下载失败';}}
function releasePreview(){previewOpen.value=false;if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value='';previewType.value='';previewGeneration++;}
watch(()=>[props.queue,props.countryId,props.partyId],()=>{paymentStatus.value='unpaid';selectedParty.value=null;globalPayments.value=false;},{flush:'sync'});
watch(()=>props.modelValue,open=>{if(open)paymentStatus.value='unpaid';},{flush:'sync'});
watch(()=>[props.modelValue,props.queue,props.countryId,props.partyId,month.value,tab.value,paymentStatus.value,selectedParty.value?.party_id,selectedParty.value?.party_name,globalPayments.value,cockpitActorKey(auth.currentUser),auth.authorizationStale],()=>{page.value=1;generation++;invalidateDetailResources();load();},{immediate:true});
watch(()=>props.modelValue,open=>{if(!open){generation++;rows.value=[];summary.value=null;available.value=[];notices.value=[];loading.value=false;previewOpen.value=false;releasePreview();}});
watch(()=>[cockpitActorKey(auth.currentUser),auth.authorizationStale],()=>{if(auth.authorizationStale){rows.value=[];summary.value=null;available.value=[];notices.value=[];loading.value=false;}},{flush:'sync'});
onUnmounted(()=>{generation++;releasePreview();});
defineExpose({openShipment});
</script>
<style scoped>.payment-status-filter{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.payment-status-filter button{border:1px solid #d6deeb;border-radius:6px;padding:8px 14px;background:#fff;color:#334155;cursor:pointer;font:inherit}.payment-status-filter button[aria-pressed=true]{background:#eef4ff;border-color:#2563eb;color:#1d4ed8;font-weight:600}.payment-status-filter button:focus-visible{outline:2px solid #2563eb;outline-offset:2px}.payment-status-filter span{margin-left:6px;font-variant-numeric:tabular-nums}.monthly-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:16px}.monthly-toolbar .el-select{width:120px}.monthly-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.monthly-metrics>div,.metric-button{padding:12px;background:#f5f7fb;border-radius:6px}.metric-button{border:0;text-align:left;cursor:pointer;color:inherit;font:inherit}.monthly-metrics small,.monthly-metrics strong{display:block}.monthly-metrics strong{margin-top:7px;overflow-wrap:anywhere}.party{display:block;color:#64748b}.voucher{display:flex;align-items:center;gap:4px}.muted,.hint{color:#64748b}.preview-image{max-width:100%;max-height:75vh;display:block;margin:auto}.preview-pdf{width:100%;height:75vh;border:0}@media(max-width:640px){.monthly-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
